    {
      "slide": 7,
      "does": "Correct the belief that rehearsal guarantees lasting memory",
      "look_at": {
        "kind": "diagram",
        "shows": "Maintaining a number in STM versus establishing an LTM trace"
      },
      "teaches": [2]
    },
    {
