      "does": "Check store characteristics and transfer with a hinge question",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": [1, 2]
    },
    {
      "slide": 9,
      "does": "Teach serial position evidence and its link to separate stores",
      "look_at": {
        "kind": "diagram",
        "shows": "Immediate and delayed recall curves with reduced delayed recency"
      },
      "teaches": [3]
    },
    {
      "slide": 10,
      "does": "Teach how KF challenges a single STM store",
      "look_at": {
        "kind": "diagram",
        "shows": "KF's contrasting verbal and visual short-term memory performance"
      },
      "teaches": [3]
